import React from "react";
import InfiniteScroll from "react-infinite-scroll-component";
import TechnicianItem from "./TechnicianItemComponent";
import FilterSheet from "./FilterSheetComponent";
import AuthCheck from "./AuthCheckComponent";
import Loader from "./LoaderComponent";

const API_URL = "https://iranaserviceapp.ir/test/api";

class TechniciansPage extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      userList: [],
      displayedUsers: [],

      searchTerm: "",

      isFilterOpen: false,
      filterProvince: "",
      filterCity: "",
      filterSpecialty: "",

      loading: true,
      loadingMore: false,
      actionLoading: false,
      authenticated: false,

      page: 1,
      hasMore: true,
    };
  }

  componentDidMount() {
    this.checkAuth();
  }

  checkAuth = async () => {
    try {
      const result = await AuthCheck();

      if (!result) {
        this.setState({
          authenticated: false,
          loading: false,
        });
        return;
      }

      this.setState(
        {
          authenticated: true,
        },
        () => {
          this.getUsers(1, true);
        }
      );
    } catch (error) {
      console.error(error);

      this.setState({
        authenticated: false,
        loading: false,
      });
    }
  };

  getUsers = async (page = 1, firstLoad = false) => {
    if (this.state.loadingMore && !firstLoad) {
      return;
    }

    if (!firstLoad && !this.state.hasMore) {
      return;
    }

    try {
      if (firstLoad) {
        this.setState({
          loading: true,
          loadingMore: false,
          page: 1,
          hasMore: true,
          userList: [],
          displayedUsers: [],
        });
      } else {
        this.setState({
          loadingMore: true,
        });
      }

      const token = localStorage.getItem("token");

      const response = await fetch(
        `${API_URL}/users?page=${page}`,
        {
          method: "GET",
          headers: {
            Authorization: `Bearer ${token}`,
            Accept: "application/json",
          },
        }
      );

      if (!response.ok) {
        throw new Error("خطا در دریافت کاربران");
      }

      const data = await response.json();

      const pagination = data?.user;

      const newUsers = Array.isArray(pagination?.data)
        ? pagination.data
        : [];

      const hasMore =
        pagination?.next_page_url !== null &&
        pagination?.next_page_url !== undefined;

      this.setState(
        (prevState) => ({
          userList:
            page === 1
              ? newUsers
              : [...prevState.userList, ...newUsers],

          page: page + 1,
          hasMore,

          loading: false,
          loadingMore: false,
        }),
        async () => {
          this.applyAllFilters();

          /*
           * اگر سرچ فعال باشد، باید صفحات بعدی را هم بگیریم
           * تا تمام کاربران بررسی شوند.
           */
          if (
            this.state.searchTerm.trim() &&
            hasMore
          ) {
            await this.getUsers(page + 1, false);
          }
        }
      );
    } catch (error) {
      console.error("getUsers error:", error);

      this.setState({
        loading: false,
        loadingMore: false,
      });
    }
  };

  fetchMoreData = () => {
    const {
      page,
      hasMore,
      loadingMore,
      searchTerm,
    } = this.state;

    if (loadingMore || !hasMore) {
      return;
    }

    /*
     * اگر سرچ فعال باشد، getUsers خودش صفحات بعدی
     * را تا آخر دریافت می‌کند.
     */
    if (searchTerm.trim()) {
      return;
    }

    this.getUsers(page, false);
  };

  handleSearch = (e) => {
    const searchTerm = e.target.value;

    this.setState(
      {
        searchTerm,
      },
      () => {
        /*
         * اگر سرچ خالی شد، فقط نتایج فعلی را فیلتر کن.
         */
        if (!searchTerm.trim()) {
          this.applyAllFilters();
          return;
        }

        /*
         * سرچ فعال شده؛ ابتدا روی اطلاعات موجود
         * جستجو می‌کنیم.
         *
         * سپس getUsers ادامه صفحات را خودش می‌گیرد.
         */
        this.applyAllFilters();

        if (this.state.hasMore) {
          const currentPage = this.state.page;

          this.getUsers(currentPage, false);
        }
      }
    );
  };

  applyAllFilters = () => {
    const {
      userList,
      searchTerm,
      filterProvince,
      filterCity,
      filterSpecialty,
    } = this.state;

    let users = [...userList];

    /*
     * Search
     */
    if (searchTerm.trim()) {
      const search = searchTerm.trim().toLowerCase();

      users = users.filter((user) => {
        const fullName = `${user.name || ""} ${
          user.family || ""
        }`
          .trim()
          .toLowerCase();

        return fullName.includes(search);
      });
    }

    /*
     * Province
     */
    if (filterProvince) {
      users = users.filter(
        (user) => String(user.state) === String(filterProvince)
      );
    }

    /*
     * City
     */
    if (filterCity) {
      users = users.filter(
        (user) => String(user.city) === String(filterCity)
      );
    }

    /*
     * Specialty
     */
    if (filterSpecialty) {
      users = users.filter((user) => {
        let specials = user.specials;

        if (!specials) {
          return false;
        }

        if (typeof specials === "string") {
          try {
            specials = JSON.parse(specials);
          } catch (error) {
            specials = specials
              .split(",")
              .map((item) => item.trim());
          }
        }

        if (!Array.isArray(specials)) {
          specials = [specials];
        }

        return specials.some((special) => {
          if (typeof special === "object" && special !== null) {
            return (
              String(special.id) === String(filterSpecialty) ||
              String(special.special_id) === String(filterSpecialty) ||
              String(special.value) === String(filterSpecialty)
            );
          }

          return String(special) === String(filterSpecialty);
        });
      });
    }

    this.setState({
      displayedUsers: users,
    });
  };

  handleDelete = async (id) => {
    if (this.state.actionLoading) {
      return;
    }

    try {
      this.setState({
        actionLoading: true,
      });

      const token = localStorage.getItem("token");

      const response = await fetch(`${API_URL}/delete`, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          Accept: "application/json",
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          id,
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data?.message || "خطا در حذف کاربر");
      }

      this.setState(
        (prevState) => ({
          userList: prevState.userList.filter(
            (user) => Number(user.id) !== Number(id)
          ),
          displayedUsers: prevState.displayedUsers.filter(
            (user) => Number(user.id) !== Number(id)
          ),
          actionLoading: false,
        }),
        () => {
          this.applyAllFilters();
        }
      );
    } catch (error) {
      console.error("delete error:", error);

      this.setState({
        actionLoading: false,
      });
    }
  };

  handleToggleStatus = async (id) => {
    if (this.state.actionLoading) {
      return;
    }

    try {
      this.setState({
        actionLoading: true,
      });

      const token = localStorage.getItem("token");

      const response = await fetch(`${API_URL}/active`, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          Accept: "application/json",
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          id,
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data?.message || "خطا در تغییر وضعیت کاربر");
      }

      /*
       * به جای اینکه کل لیست را دوباره بگیریم،
       * فقط وضعیت همان کاربر را تغییر می‌دهیم.
       */
      this.setState(
        (prevState) => {
          const updateUser = (user) => {
            if (Number(user.id) !== Number(id)) {
              return user;
            }

            return {
              ...user,
              active: Number(user.active) === 1 ? 0 : 1,
            };
          };

          return {
            userList: prevState.userList.map(updateUser),
            displayedUsers: prevState.displayedUsers.map(updateUser),
            actionLoading: false,
          };
        },
        () => {
          this.applyAllFilters();
        }
      );
    } catch (error) {
      console.error("active error:", error);

      this.setState({
        actionLoading: false,
      });
    }
  };

  handleProvinceChange = (value) => {
    this.setState(
      {
        filterProvince: value,
      },
      () => {
        this.applyAllFilters();
      }
    );
  };

  handleCityChange = (value) => {
    this.setState(
      {
        filterCity: value,
      },
      () => {
        this.applyAllFilters();
      }
    );
  };

  handleSpecialtyChange = (value) => {
    this.setState(
      {
        filterSpecialty: value,
      },
      () => {
        this.applyAllFilters();
      }
    );
  };

  resetFilters = () => {
    this.setState(
      {
        filterProvince: "",
        filterCity: "",
        filterSpecialty: "",
      },
      () => {
        this.applyAllFilters();
      }
    );
  };

  render() {
    const {
      displayedUsers,
      searchTerm,
      isFilterOpen,
      filterProvince,
      filterCity,
      filterSpecialty,
      loading,
      loadingMore,
      hasMore,
      actionLoading,
    } = this.state;

    if (loading) {
      return <Loader />;
    }

    if (!this.state.authenticated) {
      return null;
    }

    return (
      <div dir="rtl">
        {/* Header */}
        <div
          className="bg-white border-bottom"
          style={{
            position: "sticky",
            top: 0,
            zIndex: 1000,
          }}
        >
          <div className="container-fluid py-3">
            <div className="d-flex gap-2">
              <div className="flex-grow-1">
                <input
                  type="text"
                  className="form-control"
                  placeholder="جستجوی تعمیرکار..."
                  value={searchTerm}
                  onChange={this.handleSearch}
                />
              </div>

              <button
                type="button"
                className="btn btn-light border"
                onClick={() => {
                  this.setState({
                    isFilterOpen: true,
                  });
                }}
              >
                فیلتر
              </button>
            </div>
          </div>
        </div>

        {/* List */}
        <div className="container-fluid">
          <InfiniteScroll
            dataLength={this.state.userList.length}
            next={this.fetchMoreData}
            hasMore={hasMore && !searchTerm.trim()}
            scrollThreshold="200px"
            loader={
              loadingMore ? (
                <div className="text-center py-4">
                  <div
                    className="spinner-border spinner-border-sm"
                    role="status"
                  />
                  <span className="ms-2">
                    در حال بارگذاری...
                  </span>
                </div>
              ) : null
            }
            endMessage={
              displayedUsers.length > 0 ? (
                <div className="text-center text-muted py-4">
                  تمام تعمیرکاران نمایش داده شدند
                </div>
              ) : null
            }
          >
            {displayedUsers.map((technician) => (
              <TechnicianItem
                key={technician.id}
                technician={technician}
                onDelete={this.handleDelete}
                onToggleStatus={this.handleToggleStatus}
              />
            ))}
          </InfiniteScroll>

          {displayedUsers.length === 0 && !loadingMore && (
            <div className="text-center text-muted py-5">
              {searchTerm.trim()
                ? "تعمیرکاری با این مشخصات پیدا نشد"
                : "تعمیرکاری وجود ندارد"}
            </div>
          )}
        </div>

        {/* Filter */}
        {isFilterOpen && (
          <FilterSheet
            isOpen={isFilterOpen}
            onClose={() => {
              this.setState({
                isFilterOpen: false,
              });
            }}
            filterProvince={filterProvince}
            filterCity={filterCity}
            filterSpecialty={filterSpecialty}
            setFilterProvince={this.handleProvinceChange}
            setFilterCity={this.handleCityChange}
            setFilterSpecialty={this.handleSpecialtyChange}
            onReset={this.resetFilters}
          />
        )}

        {actionLoading && (
          <div
            style={{
              position: "fixed",
              inset: 0,
              background: "rgba(255,255,255,0.5)",
              zIndex: 2000,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <div className="spinner-border" role="status" />
          </div>
        )}
      </div>
    );
  }
}

export default TechniciansPage;
